import{_ as n,o as a,c as p,a5 as l}from"./chunks/framework.CXroN2RO.js";const h=JSON.parse('{"title":"第0章 学習全体マップ","description":"","frontmatter":{"title":"第0章 学習全体マップ","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"この教本のゴールはただひとつ。 > 「ゲームパッドのボタンを押してから、画面にゲームが表示されるまで」の > 一連の流れを、ブラックボックスを一切残さず説明できるようになること。"}},"headers":[],"relativePath":"guide/low-level/learning-map.md","filePath":"guide/low-level/learning-map.md"}'),e={name:"guide/low-level/learning-map.md"};function i(t,s,r,o,c,d){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="第0章-学習全体マップ" tabindex="-1">第0章 学習全体マップ <a class="header-anchor" href="#第0章-学習全体マップ" aria-label="Permalink to &quot;第0章 学習全体マップ&quot;">​</a></h1><h2 id="_0-1-最終目標の再確認" tabindex="-1">0.1 最終目標の再確認 <a class="header-anchor" href="#_0-1-最終目標の再確認" aria-label="Permalink to &quot;0.1 最終目標の再確認&quot;">​</a></h2><p>この教本のゴールはただひとつ。</p><blockquote><p><strong>「ゲームパッドのボタンを押してから、画面にゲームが表示されるまで」の 一連の流れを、ブラックボックスを一切残さず説明できるようになること。</strong></p></blockquote><p>その流れを先にネタバレしておく。今は意味が分からなくてよい。 <strong>全章を終えたとき、この図のすべての矢印を自分の言葉で説明できるようになる。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[あなたの親指] ボタンを押す</span></span>
<span class="line"><span>   │ 物理接点が閉じ、電気が流れる</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[ゲームパッドのマイコン] ボタン状態をスキャンしUSB/BTパケット化   ←第1,2章</span></span>
<span class="line"><span>   │ USBポーリング(例:1000Hz)</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[OSのUSBドライバ/HIDスタック] 割り込み→カーネルが入力レポート受信 ←第8章</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[入力API] XInput / GameInput / Windowsメッセージ                  ←第8,14章</span></span>
<span class="line"><span>   │ ゲームプロセスがポーリングで取得</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[ゲームループ] 入力→更新→描画 の毎フレーム反復                    ←第14章</span></span>
<span class="line"><span>   │ C++で書かれ、コンパイラが機械語へ変換したもの                 ←第5,6,7,9章</span></span>
<span class="line"><span>   │ CPUがキャッシュとレジスタを駆使して実行                       ←第2,3,4章</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[ゲームロジック/エンジン] シーン更新・物理・アニメ・ECS            ←第10,15,16,17章</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[レンダラ] 描画コマンドを生成し グラフィックスAPIへ               ←第12,13章</span></span>
<span class="line"><span>   │ D3D12/Vulkan → GPUドライバ → コマンドバッファ</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[GPU] 頂点シェーダ→ラスタライズ→ピクセルシェーダ→フレームバッファ ←第11,12章</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[ディスプレイ] Present/スワップチェーン→スキャンアウト→液晶が光る</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>[あなたの目] 「ジャンプした!」                        全経路 約30〜80ms</span></span></code></pre></div><h2 id="_0-2-レイヤマップ-──-何がどの章か" tabindex="-1">0.2 レイヤマップ ── 何がどの章か <a class="header-anchor" href="#_0-2-レイヤマップ-──-何がどの章か" aria-label="Permalink to &quot;0.2 レイヤマップ ── 何がどの章か&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ ゲームプログラム (あなたが日々書くコード)         │ 第14,15章</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ ゲームエンジン (Unity / UE5 / 自作)              │ 第15,16,17章</span></span>
<span class="line"><span>├──────────────────────┬──────────────────────┤</span></span>
<span class="line"><span>│ 言語ランタイム (C++/C#) │ グラフィックスAPI       │ 第9章 / 第13章</span></span>
<span class="line"><span>├──────────────────────┴──────────────────────┤</span></span>
<span class="line"><span>│ OS (プロセス・スレッド・仮想メモリ・ドライバ)      │ 第8章</span></span>
<span class="line"><span>├──────────────────────┬──────────────────────┤</span></span>
<span class="line"><span>│ コンパイラ・リンカ・ABI │ GPUドライバ            │ 第7章 / 第13章</span></span>
<span class="line"><span>├──────────────────────┴──────────────────────┤</span></span>
<span class="line"><span>│ 機械語・アセンブリ                              │ 第4章</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ CPU・メモリ・キャッシュ / GPUハードウェア         │ 第2,3章 / 第11章</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 論理回路・電気                                  │ 第1,2章(必要最小限)</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span>
<span class="line"><span>横断: 第18章 デバッグ/プロファイリング(全レイヤを覗く目)</span></span>
<span class="line"><span>統合: 最終章(全レイヤを1本のストーリーに)</span></span></code></pre></div><h2 id="_0-3-なぜこの順番か-──-依存関係グラフ" tabindex="-1">0.3 なぜこの順番か ── 依存関係グラフ <a class="header-anchor" href="#_0-3-なぜこの順番か-──-依存関係グラフ" aria-label="Permalink to &quot;0.3 なぜこの順番か ── 依存関係グラフ&quot;">​</a></h2><p>学習順の原則: <strong>「その章を理解するのに必要な知識は、必ずそれより前の章にある」</strong>。</p><ul><li><strong>ハードウェア(1〜3章)が最初</strong>な理由: C言語のポインタも、C++のパフォーマンスも、ECSの存在理由も、 すべて「メモリとCPUがどう動くか」を知らないと<strong>暗記</strong>になってしまう。 逆に知っていれば全部<strong>当然の帰結</strong>になる。</li><li><strong>アセンブリ(4章)がCより前</strong>な理由: Cの関数呼び出し・変数・ポインタを、具体的なCPUの命令列と対応させて学ぶ。 ただしCは抽象機械の規則を持つ言語であり、構造化アセンブリそのものではない。 最適化によって変数や処理が消える場合もある。 (※Cを先に浅く触り、アセンブリ後にCを深掘りする螺旋でもよい)</li><li><strong>C(5,6章)がC++(9章)より前</strong>な理由: Cの構造体・関数ポインタ・動的確保は、C++の実装を読む足場になる。 ただしC++はCと異なる型・オブジェクト寿命・所有権の規則を持つ。 <code>class</code>・<code>virtual</code>・<code>std::vector</code>は、Cの機能を包んだだけのものとして扱わない。</li><li><strong>コンパイラ/リンカ(7章)がOS(8章)の前</strong>な理由: 「実行ファイル(EXE)とは何か」を知って初めて「OSがそれをロードして プロセスにする」が理解できる。</li><li><strong>OS(8章)がGPU(11章)より前</strong>な理由: GPUとの通信はすべてドライバ=OSの仕組み(DMA、割り込み、メモリマップ)の上にある。</li><li><strong>GPU(11〜13章)がエンジン(15章〜)より前</strong>な理由: エンジンのレンダラ設計(バッチング、カリング、レンダーグラフ)は GPUとAPIの制約から逆算されたもの。制約を先に知る。</li><li><strong>Unity/UE(16,17章)が自作エンジン概念(15章)より後</strong>な理由: 一般論(エンジンとは何か)を持ってから個別実装を見ると、 「UEはここをこう解いたのか」と差分で読める。丸暗記にならない。</li></ul><h2 id="_0-4-学習の三本柱" tabindex="-1">0.4 学習の三本柱 <a class="header-anchor" href="#_0-4-学習の三本柱" aria-label="Permalink to &quot;0.4 学習の三本柱&quot;">​</a></h2><p>すべての章で、この3つを回す。</p><ol><li><strong>読む</strong> ── 教科書・ドキュメントで概念を得る</li><li><strong>書く</strong> ── 小さなコードで検証する(各章の「演習」)</li><li><strong>覗く</strong> ── デバッガ・逆アセンブリ・RenderDoc・OSSソースで実物を確認する</li></ol><p>「覗く」が最重要。<strong>この教本の差別化は「実物を覗く訓練」にある。</strong> 理解とは「教科書の記述と、画面に映る実物が一致した瞬間」に起きる。</p><h2 id="_0-5-環境構築-最初にやる" tabindex="-1">0.5 環境構築(最初にやる) <a class="header-anchor" href="#_0-5-環境構築-最初にやる" aria-label="Permalink to &quot;0.5 環境構築(最初にやる)&quot;">​</a></h2><p>Windows 11想定。以下を入れておく(全章で使う):</p><ul><li><strong>Visual Studio 2022 Community</strong>(C++デスクトップ開発ワークロード) <ul><li>逆アセンブリ表示・メモリウィンドウ・診断ツールまで使い倒す</li></ul></li><li><strong>Git</strong> と GitHubアカウント(OSSソースを読むため)</li><li><strong>RenderDoc</strong>(グラフィックスデバッガ、第12章以降)</li><li><strong>PIX on Windows</strong>(D3D12プロファイラ、第13,18章)</li><li><strong>WSL2 + Ubuntu</strong>(Linux側の実験用: ELF、straceなど第7,8章)</li><li><strong>Compiler Explorer (godbolt.org)</strong> をブックマーク(第4章から毎日使う)</li><li><strong>CMake</strong>(OSSをビルドするため)</li><li>余裕があれば: <strong>Tracy Profiler</strong>、<strong>Superluminal</strong>(体験版)</li></ul><h2 id="_0-6-学習記録のすすめ" tabindex="-1">0.6 学習記録のすすめ <a class="header-anchor" href="#_0-6-学習記録のすすめ" aria-label="Permalink to &quot;0.6 学習記録のすすめ&quot;">​</a></h2><ul><li>このフォルダに <code>notes/</code> を作り、章ごとに「自分の言葉での要約」と 「実験結果(逆アセンブリのスクショ等)」を残す。</li><li><strong>人に説明できないものは理解していない。</strong> 各章の理解度チェックは 「口頭で説明する」つもりで答えること。</li></ul><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><p>第0章は地図なので「全部」が答えだが、あえて図にする:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ボタン → [OS] → [ゲームループ] → [エンジン] → [GPU] → 画面</span></span>
<span class="line"><span>          ↑         ↑        ↑        ↑</span></span>
<span class="line"><span>       第8章     第14章   第15-17章  第11-13章</span></span>
<span class="line"><span>          └──── 下支え: CPU/メモリ(2,3章) 言語(5,6,9章) ────┘</span></span>
<span class="line"><span>                コンパイラ(4,7章)  デバッグの目(18章)</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noreferrer">WG14 N1570: C11 committee draft (5.1.2.3, 6.2.4, 6.5, 6.7.2.1)</a></li><li><a href="https://eel.is/c++draft/intro.abstract" target="_blank" rel="noreferrer">C++ working draft: Abstract machine</a></li><li><a href="https://isocpp.github.io/CppCoreGuidelines/CppCoreGuidelines#Rr-raii" target="_blank" rel="noreferrer">C++ Core Guidelines: R.1 — RAII</a></li></ul>`,26)])])}const u=n(e,[["render",i]]);export{h as __pageData,u as default};
